# Chronicle V3 evidence: real project media only, converted to WebP (full + thumbnail), with the source of every file written to SOURCE.json.
# Usage: python make_evidence.py <scratch evidence dir> <out dir>. Nothing here is generated or retouched; images are only resized.
import sys, os, json, glob
from PIL import Image
SCR, OUT = sys.argv[1], sys.argv[2]
H = "C:/Users/gokul"
LOOM = [("01_executive_overview", "Executive overview: the day's verdict, with the figures it rests on"), ("02_daily_production", "Daily production against target"), ("03_loom_performance", "Performance of each loom"),
        ("04_breakdown_insights", "Breakdown and stoppage analysis"), ("05_root_cause_analysis", "Root-cause analysis of stoppages"), ("06_abnormal_events", "Abnormal events"),
        ("07_production_loss_impact", "Production loss and its impact"), ("08_revenue_and_loss", "Revenue and loss"), ("09_workforce_intelligence", "Workforce view"), ("10_ai_agents_hub", "The explanation layer's hub")]
TEX = [("01_roc_curve", "ROC curve on the test split (n = 1,261,502)"), ("02_pr_curve", "Precision-recall curve on the test split"), ("07_calibration_reliability", "Reliability before and after isotonic calibration"),
       ("05_precision_recall_f1_vs_threshold", "Precision, recall and F1 against the decision threshold"), ("06_feature_importance", "Top 20 features by XGBoost gain"), ("04_confusion_matrix_calibrated", "Confusion matrix, calibrated, best-F1 threshold"),
       ("03_confusion_matrix_raw", "Confusion matrix, raw probability, best-F1 threshold"), ("08_prediction_distribution", "Distribution of predicted probability"), ("09_calibration_curve_map", "The isotonic calibration map")]
TT = [("mission", "Mission: ask the archive by meaning. Simulated data."), ("discover", "Semantic discovery: ranked candidates with their evidence. Simulated data."), ("changes", "Temporal change studio: one site across time. Simulated data.")]
HAC = [("Architecture", "The team's proposed architecture, from the repository"), ("Mainmodules", "Main modules, from the repository")]
jobs = []
for n, c in LOOM: jobs.append(("loom", n, f"{H}/Loom-AI/docs/presentation_slides/screenshots/{n}.png", c, "Loom-AI repository, docs/presentation_slides/screenshots/", "Screenshot of the running dashboard, committed by the team"))
for n, c in TEX: jobs.append(("texas", n, f"{SCR}/texas/{n}.png", c, f"github.com/Gokul-bit165/tdis-ML, TDIS_Ignition_BIT_V2/results/figures/{n}.png", "Figure generated by scripts/generate_visuals.py on the real test split"))
for n, c in TT: jobs.append(("terratrace", n, f"{SCR}/terratrace/{n}.png", c, "github.com/Gokul-bit165/TerraTrace at a438125, served locally and captured in Chrome at 1600 x 900 on 2026-11-13", "Capture of the real interface; all imagery and results in it are simulated"))
for n, c in HAC: jobs.append(("hac-few", n, f"{H}/HAC-FEW/Images/{n}.png", c, f"HAC-FEW repository, Images/{n}.png", "Diagram from the team's repository"))
reg = {}
for pid, n, src, cap, source, kind in jobs:
    d = os.path.join(OUT, pid); os.makedirs(d, exist_ok=True)
    im = Image.open(src).convert("RGB"); w, h = im.size
    full = im.copy(); full.thumbnail((1920, 1400)); full.save(os.path.join(d, n + ".webp"), quality=86, method=6)
    th = im.copy(); th.thumbnail((560, 420)); th.save(os.path.join(d, n + ".t.webp"), quality=78, method=6)
    reg.setdefault(pid, []).append({"file": n + ".webp", "thumb": n + ".t.webp", "w": full.size[0], "h": full.size[1], "caption": cap, "source": source, "kind": kind})
json.dump(reg, open(os.path.join(OUT, "SOURCE.json"), "w"), indent=1)
tot = sum(os.path.getsize(f) for f in glob.glob(os.path.join(OUT, "*", "*.webp")))
print({k: len(v) for k, v in reg.items()}, round(tot / 1e6, 2), "MB")
